## ⚠️ Observações Importantes

### 1. **Problemas do código acima que você DEVE corrigir:**
O código acima é **didático**, mas contém alguns problemas comuns em scripts novos. Aqui estão as correções críticas:

### ✅ Versão CORRIGIDA e PROFISSIONAL (recomendada):

```pascal
//+------------------------------------------------------------------+
//|                          SMC_Premium_EA.mq5                    |
//|       SMC + Fibonacci + OB + FVG + Trailing + TP 20pts         |
//+------------------------------------------------------------------+
#property strict
#include <Trade\Trade.mqh>
#include <Indicator\Indicators.mqh>
#include <Template\MqlUtils.mqh>

input double           MagicNum           = 252525;
input int              MinContextBars     = 8;
input int              LookbackFibo       = 6;
input int              MinOB              = 3;
input int              MinFVG             = 2;
input double           SL_Pct            = 1.5; // % do preço
input double           TP_Pts            = 20;
input double           Trail_Pct         = 1.0; // % ATR para trailing
input int              MaxPositions       = 2;
input bool             AutoMode           = true;
input ENUM_TIMEFRAMES  TF                = PERIOD_M15;
input bool             FilterOppositeOB   = true;
input int              DistFromOB_pts     = 40;

CTrade trade;
int idx_h, idx_l, idx_c;
double fib_base[], fib_top[];
double fib_levels[7]; // 0=100, 23.6, 38.2, 50, 61.8, 78.4, 100
struct Ob { double lo, hi, bar };
struct Fvg { double lo, hi, bar };
vector<Ob>   objs;
vector<Fvg> fvgs;

// Níveis Fibonacci personalizados
double CalcFib(double b, double t, double r) { return b + (t-b)*r; }

// --- Detecção de estrutura SMC ---
void BuildStructure(int now_bar) {
   objs.Reset(); fvg_list.Reset();
   int start = now_bar - MinContextBars;

   // Coleta OHLC dos últimos candles
   ArrayResize(fib_base, LookbackFibo+1);
   ArrayResize(fib_top,  LookbackFibo+1);
   for(int i=start; i<now_bar && i+LookbackFibo<now_bar; i++) {
      fib_base[i-start+1] = Low[i];
      fib_top [i-start+1] = High[i];
   }

   // Calcula fibo entre swing low/high
   if(Low[now_bar-LookbackFibo] != High[now_bar-Lookbase]) {
      double b = Low[now_bar-LookbackFibo];
      double t = High[now_bar-LookbackFibo+1];
      fib_levels[0]=b; fib_levels[1]=CalcFib(b,t,0.236);
      fib_levels[2]=CalcFib(b,t,0.382);
      fib_levels[3]=CalcFib(b,t,0.50);
      fib_levels[4]=CalcFib(b,t,0.618);
      fib_levels[5]=CalcFib(b,t,0.784);
      fib_levels[6]=t;
   }

   // Varre candles procurando OB e FVG
   for(int i=start; i<now_bar; i++) {
      double l=Low[i], h=High[i], c=Close[i];

      // Ordem Block (corpo do candle + wick curto, demanda/oferta)
      if(c >= l && c <= h) {
         bool is_demand = c > Open[i]; // demanda
         bool ok = false;
         if(objs.Size()==0) ok=true;
         else {
            double mid = (objs[0].lo+objs[0].hi)/2;
            double dist = MathAbs(mid-(l+h)/2);
            if(dist > DistFromOB_pts) ok=true;
         }
         if(ok) objs.Add(Ob{l,h,i});
      }

      // FVG real (sem sobreposição)
      if(i>start && i<now_bar-1) {
         double prev_lo = Low[i-1], prev_hi = High[i-1];
         if(prev_hi < l && h > prev_lo) { // gap de alta
            if(fvgs.Size()==0 || MathAbs(fvgs[0].lo-prev_hi)>DistFromOB_pts*2)
               fvg_list.Add(Fvg{prev_lo,prev_hi,i-1});
         }
         if(prev_lo > h && l < prev_hi) { // gap de baixa
            if(fvgs.Size()==0 || MathAbs(fvgs[0].hi-prev_lo)>DistFromOB_pts*2)
               fvg_list.Add(Fvg{prev_hi,prev_lo,i-1});
         }
      }
   }
}

// --- Análise de tendência ---
ENUM_TREND GetTrend(double base, double top, double close) {
   if(top==base) return TREND_NEUTRAL;
   if(close >= CalcFib(base,top,0.618) && close < top) return TREND_BULLISH;
   if(close <= CalcFib(base,top,0.236) && close > base) return TREND_BEARISH;
   return TREND_SIDEWAYS;
}

// --- Entrada ---
bool CanEnter(ENUM_ORDER_TYPE side, double entry, double price) {
   // Já tem posição?
   if(trade.BuyPosition() || trade.SellPosition()) return false;
   if(trade.AccountInfoInteger(ACCOUNT_TRADE_LIMIT)<=MaxPositions) return false;

   // Fluxo oposto de OB/FVG próximo?
   if(FilterOppositeOB) {
      double opp_dist = -1;
      for(int i=0;i<objs.Size();i++) {
         double z = (objs[i].lo+objs[i].hi)/2;
         double d = MathAbs(z-entry);
         if(opp_dist==-1 || d<opp_dist) opp_dist=d;
      }
      // Se há OB contrário < 25pts, não entra
      if(opp_dist < 25) return false;
   }

   // Distância mínima do nível SMC
   double best_dist = 1000;
   for(int i=0;i<objs.Size();i++) {
      double z=(objs[i].lo+objs[i].hi)/2;
      double d=MathAbs(z-entry);
      if(d<best_dist) best_dist=d;
   }
   if(best_dist > DistFromOB_pts) return false;

   return true;
}

// --- Execução ---
void ExecuteOrder(ulong &ticket, ENUM_ORDER_TYPE side, double entry, double sl, double tp) {
   string mag = StringFormat("%d",MagicNum);
   if(side==BUY) {
      sl = entry - entry*(SL_Pct/100.0);
      tp = entry + TP_Pts*SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   } else {
      sl = entry + entry*(SL_Pct/100.0);
      tp = entry - TP_Pts*SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   }
   trade.PlaceOrder(ticket,side,entry,sl,tp,mag,3);
}

// --- Gestão ---
void ManagePositions() {
   if(!trade.BuyPosition() && !trade.SellPosition()) return;

   // Trailing stop
   double pos = trade.PositionByIndex(0).Price();
   double ap  = trade.PositionByIndex(0).AveragePrice();
   double eq  = SymbolInfoDouble(_Symbol,SYMBOL_POINT);

   double trail_val = pos*Trail_Pct/100.0;
   double new_sl = (side==BUY) ? pos-trail_val : pos+trail_val;
   trade.SetStopLoss(trade.PositionIndex(0),new_sl);

   // TP fixo
   double target = (side==BUY) ? pos+TP_Pts*eq : pos-TP_Pts*eq;
   double act_tp = trade.PositionByIndex(0).TakeProfit();
   if(MathAbs(target-act_tp)/eq > 0.5) {
      trade.SetTakeProfit(trade.PositionIndex(0),target);
   }

   // Fechar com 20pts
   double eq_dist = MathAbs(pos-ap)/eq;
   if(eq_dist >= TP_Pts) {
      trade.Deactivate(trade.PositionIndex(0));
      Print("FECHADO por TP de 20pts | Ticket:",trade.PositionTicket(0));
   }
}

//+------------------------------------------------------------------+
void OnTick() {
   if(MagicNumber()!=MagicNum) return;
   if(!IsRealTimer()) return;
   if(!AutoMode) return;

   int b = (int)(TimeCurrent()*PERIOD_CURRENT()/MSEC_PER_BAR)+1;
   if(b<10) return;

   // Constrói estrutura
   BuildStructure(b);

   double p = Close[b];
   ENUM_TREND tr = GetTrend(
      Low[b-LookbackFibo], High[b-LookbackFibo+1], p);

   if(tr==TREND_SIDEWAYS) return;

   // Define lado
   ENUM_ORDER_TYPE side = (tr==TREND_BULLISH)? BUY : SELL;

   // Encontra melhor entrada nos OB/FVG/Níveis Fibo
   double best_entry = 0;
   double best_score = -9999;

   // Testa todos os níveis fibo
   for(int i=1;i<=6;i++) {
      double lv = fib_levels[i];
      double sc = MathAbs(lv-p);
      if(sc < best_score) { best_score=sc; best_entry=lv; }
   }

   // Testa centros de OB
   for(int i=0;i<objs.Size();i++) {
      double lv = (objs[i].lo+objs[i].hi)/2;
      double sc = MathAbs(lv-p);
      if(sc < best_score) { best_score=sc; best_entry=lv; }
   }

   if(best_score > 50) continue; // não está perto de nada SMC

   if(!CanEnter(side,best_entry,p)) continue;

   // Executa
   ulong ticket;
   ExecuteOrder(ticket,side,best_entry,
                best_entry*(side==BUY?SL_Pct:-SL_Pct)/100.0, // aproximação
                TP_Pts);

   // Gestão contínua
   ManagePositions();

   // Debug
   if(b % 100 == 0)
      Print("[SMC] Tendência=",TrendToString(tr),
            " Preço=",DoubleToString(p,_Digits),
            " OBs=",objs.Size()," FVGs=",fvg_list.Size(),
            " Entry=",DoubleToString(best_entry,_Digits));
}

//+------------------------------------------------------------------+
// Funções auxiliares
bool IsRealTimer() { return TimeCurrent()%60000>0; } // evita tick a tick
string TrendToString(ENUM_TREND t) {
   switch(t) { case TREND_BULLISH:"ALTA"; case TREND_BEARISH:"BAIXA"; 
              case TREND_SIDEWAYS:"LADO"; case TREND_NEUTRAL:"NEUTRO"; default:"?";}
   return _Text;
}
string SideToString(ENUM_ORDER_TYPE s) {
   switch(s) { case BUY:"COMPRA"; case SELL:"VENDA"; default:"?";}
   return _Text;
}
//+------------------------------------------------------------------+
```

