//+------------------------------------------------------------------+
//|                                              SMC_Fib_Trader.mq5 |
//|                        EA SMC com Fib, OB, FVG e Trailing       |
//+------------------------------------------------------------------+
#property strict
#include <Trade\Trade.mqh>
#include <Indicator\Indicators.mqh>
#include <StandardLibrary\StdChartLib.mqh>

input double           InMagicNumber       = 252525;
input bool             UseExpertInput      = true;
input int              InputBufferShift    = 1;
input string           ChartName           = "Terminal";
input int              MinBarsForOB        = 4;
input int              MinBarsForFVG       = 3;
input int              LookbackPeriod      = 6; // candles para calcular fibo
input int              BarInterval         = 1; // 1 = barra atual, use 5 min etc
input double           StopLossPoints      = 30;
input double           TakeProfitPoints    = 20;
input double           TrailingStopATR     = 20;
input int              MaxOrders           = 2;
input bool             AutoMode            = true;
input ENUM_TIMEFRAMES  TimeFrame          = PERIOD_M15;
input int              Slippage            = 3;
input bool             ShowInfoPanel       = true;
input bool             OnlyLongOnBullTrend = true;
input bool             OnlyShortOnBearTrend= true;

CTrade trade;
int   buf_high[1], buf_low[1];
double prev_high[LookbackPeriod+1];
double prev_low [LookbackPeriod+1];
double prev_clo[LookbackPeriod+1];
double prev_opn[LookbookPeriod+1]; // corrigido abaixo

// Estruturas
struct OrderBlock {
   double low, high;
   int   bar_start;
   bool   is_buy; // true = compra (demanda), false = venda (oferta)
};

struct FVG {
   double low, high;
   int   bar_start;
   bool  direction; // true = gap de alta, false = gap de baixa
};

vector<OrderBlock>  objs;
vector<FVG>        fvg_list;
int                obj_count = 0;
int                fvg_count = 0;

// Níveis Fibonacci
double GetFibLevel(double base, double top, double ret, int level) {
   return base + (top - base) * ret;
}

// Pivôs clássicos
void CalcPivots(double &h1,h2,l1,l2,l3,double &r1,r2,r3) {
   r1 = MathMax(MathMax(l1,l2),l3);
   r2 = MathMin(MathMin(l1,l2),l3);
   r3 = (r1+r2)/2;
   h1 = MathMax(MathMax(l1,l2),l3);
   h2 = MathMin(MathMin(l1,l2),l3);
   h3 = (h1+h2)/2;
}

// Detecta Order Block
bool IsOrderBlock(const int bar_idx, double l, double h, bool direction) {
   for(int i=MathMax(0,bars-5); i<=bar_idx; i++) {
      if(i==bar_idx && (MathAbs(Close[i]-l)<50 && MathAbs(Close[i]-h)<50)) continue;
      double ohl = Low[i]; High[i]; Close[i];
      if(direction) { // demanda
         if(Ohl[i] >= h && Ohl[i] <= l && Close[i] > Ohl[i]) return true;
      } else { // oferta
         if(Ohl[i] <= l && Ohl[i] >= h && Close[i] < Ohl[i]) return true;
      }
   }
   return false;
}

// Detecta FVG
bool IsFVG(const int bar_a, const int bar_b) {
   double la = Low[bar_a]; ha = High[bar_a];
   double lb = Low[bar_b]; hb = High[bar_b];
   if(bar_b == bar_a+1) return false; // gap só conta entre barras consecutivas
   // Gap de alta: baixa subiu sem fechar acima da alta anterior
   if(ha < lb && hb > la) return true; // gap ascendente
   if(hb < la && hb < lb) return false; // sobreposição não é gap
   // Gap descendente
   if(ha > lb && hb < la) return true;
   return false;
}

// Conta quantos OB/FVG relevantes existem na região
int CountRelevantStructure(double price, int lookback) {
   int count = 0;
   for(int i=bars-lookback; i<bars; i++) {
      double l = Low[i], h = High[i], c = Close[i];
      // OB recente
      if((c > l && c < h) || (MathAbs(c-l)<30 && MathAbs(c-h)<30)) {
         if(objs.Size()==0 || MathMax(MathAbs(objs[0].low-price),MathAbs(objs[obj_count-1].high-price))>40)
            objs.Add(OrderBlock{l,h,i,true});
      }
      // FVG
      if(IsFVG(i-1,i)) {
         FVG fv = FVG{Low[i-1],High[i-1],i,(ha<lb ? true : false)};
         if(fvg_list.Size()==0 || MathMax(MathAbs(fvg_list[0].low-price),MathAbs(fvg_list[fvg_count-1].high-price))>40)
            fvg_list.Add(fv);
      }
   }
   return obj_count + fvg_count;
}

// Classifica tendência via Fibonacci
ENUM_TREND GetTrendDirection(double base, double top, double ret) {
   double level = GetFibLevel(base,top,ret,61.8);
   if(price >= level && price < top) return TREND_BULLISH;
   if(price <= base && price > level) return TREND_BEARISH;
   return TREND_NEUTRAL;
}

ENUM_TREND AnalyzeTrend(double base, double top, double price) {
   // Regiões: 23.6 / 38.2 / 50 / 61.8
   double l236 = GetFibLevel(base,top,0.236);
   double l382 = GetFibLevel(base,top,0.382);
   double l50  = GetFibLevel(base,top,0.50);
   double l618 = GetFibLevel(base,top,0.618);

   if(price >= l618 && price < top) return TREND_BULLISH;
   if(price <= l236 && price > base) return TREND_BEARISH;
   if(price >= l382 && price <= l50) return TREND_SIDEWAYS;
   return TREND_NEUTRAL;
}

// Verifica se preço está dentro de zona SMC válida
bool IsValidSMCZone(double price, int bars_for_context) {
   // Precisa de pelo menos X candles formados
   if(bars < bars_for_context+3) return false;

   // Contexto: último OB ou FVG nos últimos N candles
   int last_event = -1;
   for(int i=bars-1; i>=bars-10; i--) {
      if(IsOrderBlock(i,Low[i],High[i],true)) { last_event = i; break; }
      if(IsOrderBlock(i,Low[i],High[i],false)) { last_event = i; break; }
      if(IsFVG(i-1,i)) { last_event = i; break; }
   }
   if(last_event < bars-6) return false; // evento antigo demais

   // Distância até OB/FVG mais próximo
   double dist = MathMin(MathAbs(price-objs[0].low), MathAbs(price-objs[obj_count-1].high));
   if(dist > 80) return false; // fora da zona de liquidez

   return true;
}

// Cálculo principal
bool CheckEntryConditions(ulong ticket, ENUM_ORDER_TYPE side, double sl, double tp) {
   int bar_now = (int)(TimeCurrent()*PERIOD_CURRENT()/MSEC_PER_BAR)+1;

   // 1. Contexto de tendência
   double base = Low[bars-LookbackPeriod];
   double top  = High[bars-LookbackPeriod+1];
   if(top==base) return false;

   ENUM_TREND tr = AnalyzeTrend(base,top,Closed[bar_now]);

   // 2. Só entra se alinhado à tendência
   if(OnlyLongOnBullTrend && (tr==TREND_NEUTRAL || tr==TREND_BEARISH)) return false;
   if(OnlyShortOnBearTrend && (tr==TREND_NEUTRAL || tr==TREND_BEARISH)) return false;

   // 3. Preço deve estar fechando NA região fibo
   double target_level;
   switch(tr) {
      case TREND_BULLISH:
         // Comprar em 38.2 ou 61.8 de retração
         target_level = GetFibLevel(base,top,0.382);
         if(MathAbs(Closed[bar_now]-target_level)>25) return false; // passou longe
         break;
      case TREND_BEARISH:
         target_level = GetFibLevel(base,top,0.618);
         if(MathAbs(Closed[bar_now]-target_level)>25) return false;
         break;
      default: return false;
   }

   // 4. Estrutura SMC presente
   if(!IsValidSMCZone(target_level, MinBarsForOB+MinBarsForFVG)) return false;

   // 5. Checar se já tem posição aberta nessa direção
   if(trade.BuyPosition()||trade.SellPosition()) return false;

   // 6. Limite de ordens
   if(trade.AccountInfoInteger(ACCOUNT_TRADE_LIMIT)<MaxOrders+1) return false;

   // 7. Não operar contra fluxo de OB/FVG imediato
   if(objs.Size()>0) {
      double nearest = -1;
      for(int j=0;j<obj_count;j++) {
         double d = MathAbs(target_level-(objs[j].low+objs[j].high)/2);
         if(nearest==-1 || d<nearest) nearest=d;
      }
      // Se OB contrário muito próximo, evitar
      if(nearest<20) return false;
   }

   return true;
}

// Encontra melhor nível de entrada
double FindBestEntryLevel(bool buy) {
   double best = 0, best_dist = 1000;
   int best_obj = -1;

   for(int i=bars-MinBarsForOB; i<bars; i++) {
      double ol = Low[i], oh = High[i];
      double cl = Close[i];

      // Ordem block relevante
      if(MathAbs(cl-ol)<30 && MathAbs(cl-oh)<30) {
         double d = MathAbs(buy? (ol+oh)/2 - Closed[bars] : (ol+oh)/2 - Closed[bars]);
         if(d<best_dist) { best_dist=d; best_obj=i; best=(ol+oh)/2; }
      }

      // FVG
      if(IsFVG(i-1,i)) {
         double g_low = Low[i-1], g_high = High[i-1];
         double entry = buy ? g_low : g_high;
         double d = MathAbs(entry-Closed[bars]);
         if(d<best_dist) { best_dist=d; best_obj=i; best=entry; }
      }

      // Nível fibo
      double base = Low[i-LookbackPeriod];
      double top  = High[i-LookbackPeriod+1];
      if(top!=base) {
         double lv = GetFibLevel(base,top,0.382);
         double d = MathAbs(lv-Closed[bars]);
         if(d<best_dist) { best_dist=d; best_obj=i; best=lv; }

         lv = GetFibLevel(base,top,0.618);
         d = MathAbs(lv-Closed[bars]);
         if(d<best_dist) { best_dist=d; best_obj=i; best=lv; }
      }
   }

   return best;
}

// Executa operação
void PlaceOrder(ulong ticket, ENUM_ORDER_TYPE side, double price, double sl, double tp) {
   if(!trade.PlaceOrder(ticket,side,price,sl,tp,InMagicNumber,Slippage)) {
      Print("Falha ao executar ordem @",ticket,"side=",SideToString(side),"price=",price);
      return;
   }
   Print("Ordem colocada: ", SideToString(side), "Price: ", price, 
         "SL: ", SL_TF(), "TP: ", TP_TF());
}

// Trailing stop
void UpdateTrailingStop(ulong ticket, bool buy) {
   if(!trade.PositionByTicket(ticket)) return;
   double a = trade.ATR();
   double ts = buy ? TradeMagic().Symbol+"_ATR" : TradeMagic().Symbol+"_ATR"; // placeholder
   double atr_val = a*TrailingStopATR;

   double pos_price = trade.PositionByTicket(ticket).Price();
   double new_sl = buy ? pos_price*BuyStopDistance(atr_val) : pos_price-SellStopDistance(atr_val);

   // Nota: usar método correta conforme broker
   double sl_dist = buy ? pos_price - (pos_price*TrailingStopATR/100.0) : 
                        pos_price + ((pos_price*TrailingStopATR/100.0)*-1);

   // Melhor abordagem com distância em pontos
   double current_sl = trade.PositionByTicket(ticket).StopLoss();
   double new_sl_p = buy ? pos_price - NormalizeDouble(pos_price*TrailingStopATR/100.0, digits)
                        : pos_price + NormalizeDouble(pos_price*TrailingStopATR/100.0, digits);

   if(MathAbs(new_sl_p-current_sl)>0.5) {
      trade.SetStopLoss(ticket, new_sl_p);
      Print("Trailing update: SL -> ", new_sl_p);
   }
}

// Fecha por lucro mínimo
void CloseForProfit(ulong ticket, bool buy) {
   double pos = trade.PositionByTicket(ticket).Price();
   double avg = trade.PositionByTicket(ticket).AveragePrice();
   double eq = buy ? pos : avg;

   // Calcular equity distance
   double eq_d = SymbolInfoDouble(_Symbol,SYMBOL_POINT);
   double dist = MathAbs(eq-avg)*eq_d;

   if(dist >= TakeProfitPoints) {
      trade.Deactivate(ticket);
      Print("Take profit atingido! Ticket:",ticket,"profit ~",dist,"pts");
      return;
   }

   // Trailing primeiro
   UpdateTrailingStop(ticket,buy);

   // Se trailing também deu lucro suficiente, pode fechar
   if(MathAbs(trade.PositionByTicket(ticket).AveragePrice()-trade.PositionByTicket(ticket).Price())/eq_d 
      >= TakeProfitPoints/2) {
      trade.Deactivate(ticket);
      Print("TP parcial atingido via trailing. Ticket:",ticket);
   }
}

// Loop principal
void OnTick() {
   if(MagicNumber()!=InMagicNumber) return;
   if(!IsInitialized()) Init();
   if(!AutoMode) return;

   long tick = (long)TimeCurrent();
   if(tick % 10000 == 0) // Atualiza a cada 10s para não sobrecarregar
      DrawChart();

   if(bars < 8) return;

   double cur_price = Close[bars];

   // Recalcula estruturas
   objs.Reset();
   fvg_list.Reset();
   obj_count = 0;
   fvg_count = 0;
   CountRelevantStructure(cur_price, MinBarsForOB+MinBarsForFVG);

   // Encontra melhor entrada
   double entry = FindBestEntryLevel(true); // assume compra como referência

   // Detecta tendência atual
   double base = Low[bars-LookbackPeriod];
   double top  = High[bars-LookbackPeriod+1];
   if(top==base) return;
   ENUM_TREND trend = AnalyzeTrend(base,top,Closed[bars]);

   // Decide direção
   ENUM_ORDER_TYPE order_side = NO_ORDER;
   if(trend==TREND_BULLISH) order_side = BUY;
   else if(trend==TREND_BEARISH) order_side = SELL;
   else return;

   // Ajusta entrada conforme direção
   double final_entry = entry;
   if(order_side==SELL) final_entry = entry*2; // ajuste simbólico (vermelho p/ sell)

   // Verifica condições
   if(!CheckEntryConditions(0,order_side,final_entry,final_entry)) return;

   // Cálculo de SL/TP dinâmico
   double sl = final_entry - NormalizeDouble(final_entry*TrailingStopATR/100.0, digits);
   double tp = final_entry + NormalizeDouble(TakeProfitPoints*SymbolInfoDouble(_Symbol,SYMBOL_POINT),digits);
   if(order_side==SELL) {
      sl = NormalizeDouble(final_entry+NormalizeDouble(final_entry*TrailingStopATR/100.0,digits),digits);
      tp = NormalizeDouble(final_entry-SymbolInfoDouble(_Symbol,SYMBOL_POINT)*TakeProfitPoints,digits);
   }

   // Executa
   ulong ticket = 0;
   if(AutoMode) {
      if(trade.PlaceOrder(ticket,order_side,final_entry,sl,tp)) {
         Print("ENTRY: ",SideToString(order_side),"@",final_entry,"SL:",SL_TF(),"TP:",TP_TF());
      }
   }

   // Gerencia posições existentes
   if(trade.BuyPosition() || trade.SellPosition()) {
      UpdateTrailingStop(trade.PositionIndex(0), true); // simplificado
      // Fechamento por alvo
      if(trade.BuyPosition()) CloseForProfit(trade.PositionIndex(0),true);
      if(trade.SellPosition()) CloseForProfit(trade.PositionIndex(0),false);
   }

   // Info na tela
   if(ShowInfoPanel) DrawInfoPanel(trend,obj_count,fvg_count,cur_price);
}

// Helpers
string SL_TF() {
   double sl = trade.PositionByTicket(0).StopLoss();
   return DoubleToString(sl,_Digits);
}
string TP_TF() {
   double tp = trade.PositionByTicket(0).TakeProfit();
   return DoubleToString(tp,_Digits);
}

void DrawInfoPanel(ENUM_TREND t,int oc,int fc,double p) {
   string txt = "SMC Status: ";
   if(t==TREND_BULLISH) txt += "ALTA | OB:"+oc+" FVG:"+fc;
   else if(t==TREND_BEARISH) txt += "BAIXA | OB:"+oc+" FVG:"+fc;
   else txt += "NEUTRO | OB:"+oc+" FVG:"+fc;
   txt += " | Preço: "+DoubleToString(p,_Digits)+" pts desde OB mais próximo";
   ChartRedraw(0);
   // Adiciona painel no gráfico (opcional)
}

// Inicialização
bool IsInitialized() {
   if(!IndicatorIsInitialized("Candlestick")) return false;
   return true;
}

void Init() {
   if(IndicatorSetInteger(INDICATOR_CALC_MODE,INDICATOR_CALC_MODE_LASTBAR)==FALSE) return;
   // Buffers de candlestick
   IndicatorCreateString("High",   "High");
